    private static async Task GitHubTests(ProofSuite s,string root)
    {
        var h=new GitHubFixture();var adapter=new GitHubRepairAdapter("gh.exe",root,h);
        await s.CheckAsync("real GitHub source adapter selects exact branch and excludes runtime DB before fetch",async()=>{var source=await adapter.PrepareAsync(default);ProofSuite.Equal(source.Files.Length,2);ProofSuite.True(h.Calls.All(q=>!q.Arguments.Any(a=>a.Contains("sensitive-blob",StringComparison.Ordinal))));ProofSuite.True(h.Calls.Any(q=>q.Arguments.Contains("repos/"+RepairScope.Repository+"/git/ref/heads/"+RepairScope.BaseBranch)));});
        await s.CheckAsync("incomplete GitHub tree fails closed without archive clone fallback",async()=>{h.Truncated=true;await ProofSuite.ThrowsAsync(()=>adapter.PrepareAsync(default));h.Truncated=false;});
        await s.CheckAsync("GitHub publisher verifies account push permission",async()=>{h.Permission=false;await ProofSuite.ThrowsAsync(()=>adapter.PrepareAsync(default));h.Permission=true;});
        await s.CheckAsync("corrupt source blob hash is rejected",async()=>{h.Corrupt=true;await ProofSuite.ThrowsAsync(()=>adapter.PrepareAsync(default));h.Corrupt=false;});
        var job=Job();job=job with{ReviewHash=RealRepairCoordinator.ReviewDigest(job)};h.Job=job;
        await s.CheckAsync("real GitHub adapter creates deterministic commit per-job branch and Draft PR targeting feature",async()=>{var url=await adapter.PublishAsync(job,_=>{},default);ProofSuite.True(url.EndsWith("/pull/123",StringComparison.Ordinal));var post=h.Calls.Where(q=>q.Arguments.Contains("POST")).ToArray();ProofSuite.True(post.Length==4);var pr=post.Single(q=>q.Arguments.Any(a=>a.EndsWith("/pulls",StringComparison.Ordinal)));using var d=JsonDocument.Parse(pr.Input!);ProofSuite.True(d.RootElement.GetProperty("draft").GetBoolean());ProofSuite.Equal(d.RootElement.GetProperty("base").GetString(),RepairScope.BaseBranch);ProofSuite.True(!h.Calls.Any(q=>q.Arguments.Contains("PATCH")||q.Arguments.Any(a=>a.Contains("merge",StringComparison.Ordinal))));});
        await s.CheckAsync("repeat publication and PR requery validate existing result with zero extra writes",async()=>{var count=h.Writes;await adapter.PublishAsync(job,_=>{},default);await adapter.FindPrAsync(job,default);ProofSuite.Equal(h.Writes,count);});
        await s.CheckAsync("remote branch content conflict is never accepted as published result",async()=>{h.Conflict=true;await ProofSuite.ThrowsAsync(()=>adapter.FindPrAsync(job,default));h.Conflict=false;});
        await s.CheckAsync("moved integration base blocks publication before write",async()=>{h.Published=false;h.BaseMoved=true;var before=h.Writes;await ProofSuite.ThrowsAsync(()=>adapter.PublishAsync(job,_=>{},default));ProofSuite.Equal(h.Writes,before);h.BaseMoved=false;});
        await s.CheckAsync("missing-response branch resume is read-only and validates exact tree",async()=>{var before=h.Writes;ProofSuite.True(await adapter.CanResumeAsync(job,default));ProofSuite.Equal(h.Writes,before);});
        s.Check("commit identity and time are stable across replay",()=>{ProofSuite.Equal(GitHubRepairAdapter.CommitHash(job,new('e',40)),GitHubRepairAdapter.CommitHash(job,new('e',40)));ProofSuite.True(GitHubRepairAdapter.CommitHash(job with{Created=job.Created.AddSeconds(1)},new('e',40))!=GitHubRepairAdapter.CommitHash(job,new('e',40)));});
    }
    private static async Task WorkspaceTests(ProofSuite s,string root,NativeToolRunner runner)
    {
        var git=Locate("git");if(git is null)throw new InvalidOperationException("Git required for phase7 proof");
        var files=new[]{new SourceBlob(Code,ProtocolJson.Utf8.GetBytes("module.exports=1;")),new SourceBlob(RepairScope.Derived[0],ProtocolJson.Utf8.GetBytes("{\"ready\":false,\"hashes\":{\"src/incident-proof.js\":\"synthetic\"}}")),new SourceBlob(RepairScope.Derived[1],ProtocolJson.Utf8.GetBytes("{\"schemaVersion\":1,\"files\":{\"src/incident-proof.js\":\"synthetic\",\"app-release.json\":\"synthetic\"}}")),new SourceBlob(Prefix+"tests/trusted.test.cjs",ProtocolJson.Utf8.GetBytes("// fixed baseline")),new SourceBlob(Prefix+"releases/v0.1.7/src/server.js",ProtocolJson.Utf8.GetBytes("// immutable live reference"))};
        var ws=new RepairWorkspace(Path.Combine(root,"actual-git"),git,runner);var hashes=await ws.CreateAsync(new(new('a',40),new('b',40),"synthetic",1,files),default);var job=Job() with{Baseline=hashes};
        s.Check("isolated source has no Git credential metadata or copied runtime records",()=>ProofSuite.True(!Directory.Exists(Path.Combine(ws.Source,".git"))&&Directory.Exists(Path.Combine(root,"actual-git","BrokerGit"))));
        await s.CheckAsync("real Git diff and derived manifests bind edited code plus reproduction",async()=>{File.WriteAllText(RepairScope.Resolve(ws.Source,Code),"module.exports=2;");var repro=RepairScope.Resolve(ws.Source,RepairScope.Repro);File.WriteAllText(repro,"// synthetic reproduction");var result=await ws.InspectAsync(job,default);ProofSuite.True(result.Diff.Contains("+module.exports=2;",StringComparison.Ordinal)&&result.Changes.Any(p=>p.Path==RepairScope.Derived[0])&&result.Changes.Any(p=>p.Path==RepairScope.Derived[1]));var repeated=await ws.InspectAsync(job,default);ProofSuite.Equal(result.Digest,repeated.Digest);});
        await s.CheckAsync("trusted tests and before snapshot stay immutable during verification copy",async()=>{await ws.PrepareTestsAsync(job,default);ProofSuite.Equal(File.ReadAllText(RepairScope.Resolve(ws.Before,Code)),"module.exports=1;");ProofSuite.True(!File.Exists(RepairScope.Resolve(ws.Before,RepairScope.Repro))&&File.Exists(RepairScope.Resolve(ws.TestBefore,RepairScope.Repro)));ProofSuite.Equal(File.ReadAllText(RepairScope.Resolve(ws.Verify,Prefix+"tests/trusted.test.cjs")),"// fixed baseline");});
        await s.CheckAsync("live v017 edits are rejected before diff publication",async()=>{var path=RepairScope.Resolve(ws.Source,Prefix+"releases/v0.1.7/src/server.js");File.WriteAllText(path,"// disallowed");await ProofSuite.ThrowsAsync(()=>ws.InspectAsync(job,default));File.WriteAllBytes(path,files.Last().Bytes);});
        await s.CheckAsync("agent manifest tampering is rejected",async()=>{File.WriteAllText(RepairScope.Resolve(ws.Source,RepairScope.Derived[0]),"{\"ready\":true}");await ProofSuite.ThrowsAsync(()=>ws.InspectAsync(job,default));});
        s.Check("source path traversal and alternate streams are rejected",()=>{foreach(var p in new[]{"../code.js","C:/code.js","dir/code.js:stream","dir\\code.js"})ProofSuite.Throws(()=>RepairScope.Resolve(ws.Source,p));});
    }
    private static async Task FullSourceProof(ProofSuite s,string root,BackendLayout backend,NativeToolRunner runner)
    {
        var repo=Path.GetFullPath(Path.Combine(backend.Root,"../../../.."));if(!File.Exists(Path.Combine(repo,".git","HEAD")))return;var git=Locate("git")!;
        var listed=await runner.RunAsync(new(git,["ls-files"],repo),default);
        var files=listed.Output.Split('\n',StringSplitOptions.RemoveEmptyEntries).Where(RepairScope.Exportable).Select(p=>new SourceBlob(p,File.ReadAllBytes(RepairScope.Resolve(repo,p)))).ToArray();
        var ws=new RepairWorkspace(Path.Combine(root,"full-source"),git,runner);RealRepairJob? job=null;
        await s.CheckAsync("complete allowed source snapshot excludes data and passes real bundle manifest verification",async()=>{
            var baseline=await ws.CreateAsync(new(new('a',40),new('b',40),"synthetic",1,files),default);job=Job() with{Baseline=baseline};
            File.WriteAllText(RepairScope.Resolve(ws.Source,Code),"module.exports=2;");File.WriteAllText(RepairScope.Resolve(ws.Source,RepairScope.Repro),"const test=require('node:test'),assert=require('node:assert/strict');test('synthetic source copy',()=>assert.equal(require('../../releases/v0.2.0/src/incident-proof'),2));");
            var changed=await ws.InspectAsync(job,default);ProofSuite.True(changed.Changes.Any(p=>p.Path==Code));
            var result=await runner.RunAsync(new(backend.Node,[RepairScope.Prefix+"control-center/scripts/backend-manifest.cjs"],ws.Source),default);ProofSuite.Equal(result.Exit,0);
            await ws.PrepareTestsAsync(job,default);
            var before=await runner.RunAsync(new(backend.Node,["--test",RepairScope.Repro],ws.TestBefore),default);var after=await runner.RunAsync(new(backend.Node,["--test",RepairScope.Repro],ws.Verify),default);ProofSuite.True(before.Exit!=0&&after.Exit==0);
        });
    }
    private static async Task CoordinatorTests(ProofSuite s,string root)
    {
        using var crypto=new Crypto();var store=new RealRepairStore(Path.Combine(root,"ledger"),crypto);var gh=new GitHub();var cli=new Codex();var work=new Workspace(root);var co=new RealRepairCoordinator(store,gh,cli,_=>work);var input=Input();var packet=RealRepairCoordinator.ExecutionPreview(input);
        await s.CheckAsync("actual execution requires activation and exact external preview approval",async()=>{await ProofSuite.ThrowsAsync(()=>co.StartAsync(input,packet,AnalysisConsent.Approve("real-codex",packet),false,_=>{},default));await ProofSuite.ThrowsAsync(()=>co.StartAsync(input,packet,AnalysisConsent.Approve("other",packet),true,_=>{},default));ProofSuite.Equal(cli.Calls,0);});
        RealRepairJob? job=null;
        await s.CheckAsync("real workflow adapter contract completes isolation edit tests and review without publishing",async()=>{job=await co.StartAsync(input,packet,AnalysisConsent.Approve("real-codex",packet),true,_=>{},default);ProofSuite.Equal(job.State,"review");ProofSuite.Equal(gh.Writes,0);ProofSuite.True(job.ReviewHash==RealRepairCoordinator.ReviewDigest(job));});
        await s.CheckAsync("duplicate execute reuses job and never repeats paid inference",async()=>{var saved=await co.StartAsync(input,packet,AnalysisConsent.Approve("real-codex",packet),true,_=>{},default);ProofSuite.Equal(saved.Id,job!.Id);ProofSuite.Equal(cli.Calls,1);});
        s.Check("job store is encrypted separately and preserves CAS revision",()=>{var bytes=File.ReadAllBytes(Path.Combine(store.Root,job!.Id+".dpapi"));ProofSuite.True(bytes.AsSpan().IndexOf(ProtocolJson.Utf8.GetBytes("합성 질문"))<0);ProofSuite.Equal(new RealRepairStore(store.Root,crypto).Read(job.Id).State,"review");ProofSuite.Throws(()=>store.Save(job,0));});
        await s.CheckAsync("publication requires separate enable and exact diff approval",async()=>{var preview=RealRepairCoordinator.PublicationPreview(job!);await ProofSuite.ThrowsAsync(()=>co.PublishAsync(job!.Id,AnalysisConsent.Approve("real-github",preview),false,_=>{},default));await ProofSuite.ThrowsAsync(()=>co.PublishAsync(job!.Id,AnalysisConsent.Approve("real-codex",preview),true,_=>{},default));ProofSuite.Equal(gh.Writes,0);});
        await s.CheckAsync("changed diff after tests blocks GitHub write",async()=>{work.Mutate=true;await ProofSuite.ThrowsAsync(()=>co.PublishAsync(job!.Id,AnalysisConsent.Approve("real-github",RealRepairCoordinator.PublicationPreview(job)),true,_=>{},default));ProofSuite.Equal(gh.Writes,0);work.Mutate=false;});
        await s.CheckAsync("unknown publication response persists uncertainty and blocks automatic replay",async()=>{gh.FailWrite=true;await ProofSuite.ThrowsAsync(()=>co.PublishAsync(job!.Id,AnalysisConsent.Approve("real-github",RealRepairCoordinator.PublicationPreview(job)),true,_=>{},default));ProofSuite.Equal(store.Read(job!.Id).State,"publication-uncertain");await ProofSuite.ThrowsAsync(()=>co.PublishAsync(job!.Id,AnalysisConsent.Approve("real-github",RealRepairCoordinator.PublicationPreview(job)),true,_=>{},default));ProofSuite.Equal(gh.Writes,1);});
        await s.CheckAsync("read-only requery resumes approval state without any write",async()=>{var saved=await co.RequeryAsync(job!.Id,default);ProofSuite.Equal(saved.State,"review");ProofSuite.Equal(gh.Writes,1);job=saved;});
        await s.CheckAsync("explicit second approval publishes once and read requery remains idempotent",async()=>{gh.FailWrite=false;job=await co.PublishAsync(job!.Id,AnalysisConsent.Approve("real-github",RealRepairCoordinator.PublicationPreview(job)),true,_=>{},default);ProofSuite.Equal(job.State,"published");var count=gh.Writes;await co.RequeryAsync(job.Id,default);ProofSuite.Equal(gh.Writes,count);});
        foreach(var mode in new[]{"tests-failed","timeout","cancelled","disconnected","isolation"})await s.CheckAsync("real job failure remains unpublishable without retry: "+mode,async()=>{cli.Mode=mode;var i=Input("manual:"+mode);var p=RealRepairCoordinator.ExecutionPreview(i);var saved=await co.StartAsync(i,p,AnalysisConsent.Approve("real-codex",p),true,_=>{},default);ProofSuite.True(saved.State is "failed" or "timeout" or "cancelled" or "uncertain" or "blocked");var count=cli.Calls;await co.StartAsync(i,p,AnalysisConsent.Approve("real-codex",p),true,_=>{},default);ProofSuite.Equal(cli.Calls,count);});
        s.Check("restart marks abandoned execution uncertain and never replays",()=>{var j=Job() with{State="running",ReportRevision="abandoned",Packet="other",PacketHash=PrivacyPacket.Hash("other")};store.Save(j with{Revision=0},0);ProofSuite.Equal(co.History(j.ReportId).Single(x=>x.Id==j.Id).State,"uncertain");});
        s.Check("active job lease prevents restart reclassification",()=>{var j=store.Save(Job() with{Revision=0,State="running",ReportRevision="active",Packet="active",PacketHash=PrivacyPacket.Hash("active")},0);using var held=store.Activity(j.Id);ProofSuite.Equal(co.History(j.ReportId).Single(x=>x.Id==j.Id).State,"running");});
        s.Check("settings default disabled and persist paths only",()=>{var settings=new RealRepairOptionsStore(Path.Combine(root,"settings"));ProofSuite.True(!settings.Load().ExecutionEnabled&&!settings.Load().PublicationEnabled);settings.Save(new("codex.exe","git.exe","gh.exe",true,false));ProofSuite.True(settings.Load().ExecutionEnabled);var json=File.ReadAllText(Path.Combine(root,"settings","real-tools.local.json"));ProofSuite.True(!json.Contains("token",StringComparison.OrdinalIgnoreCase)&&!json.Contains("key",StringComparison.OrdinalIgnoreCase));});
        if(OperatingSystem.IsWindows())s.Check("real repair DPAPI cannot decrypt manual report ciphertext or vice versa",()=>{var native=new RealRepairStore(Path.Combine(root,"native-dpapi"),new WindowsRealRepairProtection());var saved=native.Save(Job() with{Revision=0},0);ProofSuite.Equal(new RealRepairStore(native.Root,new WindowsRealRepairProtection()).Read(saved.Id).Id,saved.Id);ProofSuite.Throws(()=>new WindowsReportProtection().Unprotect(File.ReadAllBytes(Path.Combine(native.Root,saved.Id+".dpapi"))));});
    }
    private static string? Locate(string name){foreach(var root in (Environment.GetEnvironmentVariable("PATH")??"").Split(Path.PathSeparator)){var p=Path.Combine(root,OperatingSystem.IsWindows()?name+".exe":name);if(File.Exists(p))return p;}return null;}
